{"path":"ledger/importer.py","content":""""Import bank CSV exports into Transaction objects.

Expected columns (any order, header row required): Date, Description, Amount, Memo (optional).
"""
import csv
from datetime import date
from io import StringIO

from .models import Transaction

REQUIRED = ("date", "description", "amount")


def _parse_amount(text: str) -> float:
    text = text.strip().replace("$", "").replace(" ", "")
    if text.startswith("(") and text.endswith(")"):
        text = "-" + text[1:-1]
    # Allow thousands separators (e.g. "-1,250.00").
    text = text.replace(",", "")
    return float(text)


def _rows_with_header(text: str):
    """Yield (header, cells) rows, skipping blank lines and quoted newlines."""
    reader = csv.reader(StringIO(text))
    lines = []
    for cells in reader:
        # Blank lines (and lines with only whitespace) produce an empty row
        # or a single empty/whitespace cell; skip them.
        if not cells or all(c.strip() == "" for c in cells):
            continue
        lines.append(cells)
    if not lines:
        return None, []
    header = [h.strip().lower() for h in lines[0]]
    return header, lines[1:]


def parse_rows(text: str):
    header, lines = _rows_with_header(text)
    if header is None:
        return []
    missing = [c for c in REQUIRED if c not in header]
    if missing:
        raise ValueError(f"missing columns: {', '.join(missing)}")
    rows = []
    for cells in lines:
        # Pad short rows so every header column maps to a value.
        cells = cells + [""] * (len(header) - len(cells))
        rows.append(dict(zip(header, cells)))
    return rows


def import_csv(text: str) -> list[Transaction]:
    out = []
    for row in parse_rows(text):
        out.append(Transaction(
            day=date.fromisoformat(row["date"].strip()),
            description=row["description"].strip(),
            amount=_parse_amount(row["amount"]),
            memo=(row.get("memo") or "").strip(),
        ))
    return out


def import_file(path: str) -> list[Transaction]:
    with open(path, encoding="utf-8-sig") as f:
        return import_csv(f.read())
